code.text:
@layer base, utilities;

@layer base {
  #main p { color: blue; }
}
@layer utilities {
  p { color: green; }
}

div {
  background-color: #cce5ff;
  background: url("pattern.png") no-repeat center/cover;
}

button {
  transition: background 0.5s;
}
button:hover {
  background: black;
  transform: scale(1.1);
}

.grid {
  display: grid;
  width: 640px;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.cards {
  display: grid;
  width: 1100px;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
}

.page {
  display: grid;
  grid-template-columns: 200px 1fr;
  grid-template-areas:
    "header header"
    "nav    main"
    "footer footer";
}
